    # Determine scaling factor
    if int_w > 0 and pattern and int_w % len(pattern[0]) == 0:
        scale = int_w // len(pattern[0])
    else:
        scale = 1

    # Create output
    frame_h = r2 - r1 + 1
    frame_w = c2 - c1 + 1
